// Pure validation — no network calls, so no this.helpers/$helpers concern here.
const body = $json?.body ?? $json ?? {};

const track = (body.track || '').toString().trim();
const raceNumberRaw = body.race_number;
const raceNumber = (raceNumberRaw === undefined || raceNumberRaw === null || raceNumberRaw === '')
  ? null
  : Number(raceNumberRaw);
const date = (body.date || new Date().toISOString().split('T')[0]).toString();

const errors = [];
if (!track) errors.push('track is required');
if (raceNumber === null || Number.isNaN(raceNumber)) errors.push('race_number is required and must be a number');

return [{
  json: {
    track,
    race_number: raceNumber,
    date,
    valid: errors.length === 0,
    errors
  }
}];

