// ============================================================================
// ASSEMBLE CONTEXT — PROVIDER-AGNOSTIC SEAM
// ============================================================================
// This node ONLY reads $input (the immediate upstream node's output), never a
// named node reference back to "Sample Race Card". That's deliberate: to swap
// sample data for a real provider later, replace the Sample Race Card node
// with a real provider node/chain that ends by emitting this exact shape —
// nothing in this node, and nothing in the Bobby Vegas Analysis prompt below
// it, needs to change.
//
// REQUIRED INPUT CONTRACT (see Sample Race Card's header for the full spec):
//   { race: { track, raceNumber, date, distance, surface, condition,
//              weather, raceType, purse, dataSource },
//     horses: [{ postPosition, name, morningLine, jockey, jockeyWinPct,
//                 trainer, trainerWinPct, currentClass, daysSinceLastRace,
//                 runningStyle, lastStarts: [{ daysAgo, finish, fieldSize,
//                 speedFigure, distance, surface, class, track }] }] }
// ============================================================================

const input = $input.first().json;
const race = input.race || {};
const horses = input.horses || [];

const avg = arr => arr.length ? Math.round(arr.reduce((a, b) => a + b, 0) / arr.length) : null;

// Rough class rank so a move up/down can be labeled automatically from free-text
// class strings. Extend this map as real-provider class strings are seen.
const CLASS_RANK = {
  'claiming': 1, 'allowance n1x': 3, 'allowance n2x': 4, 'allowance n3x': 5,
  'allowance optional claiming (n1x)': 3, 'allowance optional claiming (n2x)': 4,
  'allowance': 3, 'stakes': 6, 'graded stakes': 7
};
const rankOf = (label) => {
  const key = (label || '').toLowerCase().trim();
  for (const [k, v] of Object.entries(CLASS_RANK)) if (key.includes(k)) return v;
  return null;
};

const horseLines = horses.map(h => {
  const lastStarts = h.lastStarts || [];
  const figs = lastStarts.slice(0, 3).map(s => s.speedFigure).filter(v => typeof v === 'number');
  const avgFig = avg(figs);
  const figStr = figs.length ? figs.join(', ') + (avgFig !== null ? ` (avg ${avgFig})` : '') : 'no recent figures';

  const lastClassRank = rankOf(lastStarts[0]?.class);
  const currentRank = rankOf(h.currentClass);
  let classMove = 'class move unclear from data';
  if (lastClassRank !== null && currentRank !== null) {
    if (currentRank > lastClassRank) classMove = 'moving UP in class';
    else if (currentRank < lastClassRank) classMove = 'moving DOWN in class (drop)';
    else classMove = 'same class level';
  }

  const lastSurface = lastStarts[0]?.surface;
  const lastDistance = lastStarts[0]?.distance;
  const surfaceFit = lastSurface && race.surface && lastSurface !== race.surface
    ? `SURFACE SWITCH: last raced on ${lastSurface}, today is ${race.surface} — unproven on today's surface`
    : 'surface matches recent starts';
  const distanceFit = lastDistance && race.distance && lastDistance !== race.distance
    ? `distance change: last at ${lastDistance}, today ${race.distance}`
    : 'distance matches recent starts';

  const daysOff = h.daysSinceLastRace;
  const layoffNote = (typeof daysOff === 'number' && daysOff >= 60)
    ? `LAYOFF: ${daysOff} days since last start`
    : `${daysOff ?? 'unknown'} days since last start`;

  const extraNote = h.note ? ` NOTE: ${h.note}` : '';

  return [
    `#${h.postPosition} ${h.name} — ML ${h.morningLine} — ${h.runningStyle || 'running style unknown'}`,
    `   Jockey: ${h.jockey} (${h.jockeyWinPct}% wins) | Trainer: ${h.trainer} (${h.trainerWinPct}% wins)`,
    `   Last 3 speed figures: ${figStr}`,
    `   Class: ${h.currentClass} — ${classMove}`,
    `   ${surfaceFit}; ${distanceFit}`,
    `   ${layoffNote}${extraNote}`
  ].join('\n');
});

const paceGroups = { 'Early speed': [], 'Pace presser': [], 'Stalker': [], 'Closer': [] };
for (const h of horses) {
  const style = h.runningStyle;
  if (paceGroups[style]) paceGroups[style].push(h.name);
}
const paceStr = Object.entries(paceGroups)
  .filter(([, names]) => names.length)
  .map(([style, names]) => `${style}: ${names.join(', ')}`)
  .join(' | ') || 'Pace mix unclear from data';

const raceHeader = `🏇 RACE: ${race.track} — Race ${race.raceNumber} — ${race.distance} — ${race.surface} — ${race.condition}`;

return [{
  json: {
    raceHeader,
    raceMeta: race,
    fieldSnapshotStr: horseLines.join('\n\n'),
    paceStr,
    weatherStr: race.weather || 'Weather not available',
    purseStr: race.purse || 'Purse not available',
    dataSource: race.dataSource || 'UNKNOWN',
    horseCount: horses.length,
    horsesRaw: horses
  }
}];
